const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state,selected,tab='tasks',filter='all';const key='agenct-demo-v1';
function seed(){let a=Hub.create('001','修复 WUA 报告单位显示错误','仅修改报告显示层并补充回归测试；不得改动 HSI/WUA 公式。交付待审查 MR，禁止自动合并。');let b=Hub.create('002','为空数据导出补充回归测试','在测试仓库补充空数据边界测试，保持现有导出接口不变。');for(const x of ['accept','start','publish','verify'])Hub.act(b,x,'Bob');return {tasks:[a,b],next:3};}try{state=JSON.parse(localStorage.getItem(key))||seed();if(!Array.isArray(state.tasks))state=seed();}catch{state=seed();}selected=state.tasks[0]?.id;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('浏览器存储不可用，当前更改仅在本次页面有效');}}function toast(m){$('#toast').textContent=m;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500);}function badge(t){return `<span class="badge ${t.status}">${Hub.labels[t.status]}</span>`;}function button(action,text,cls='secondary'){return `<button class="${cls}" data-action="${action}">${text}</button>`;}
function render(){const tasks=state.tasks;$('#stats').innerHTML=[['全部任务',tasks.length,'单仓库 · habitat-demo'],['等待人工',tasks.filter(t=>['awaiting_owner','ready','unknown'].includes(t.status)).length,'接单、核对与验收'],['已完成',tasks.filter(t=>t.status==='completed').length,'已验收 · 不代表已合并'],['模拟费用','$'+tasks.reduce((s,t)=>s+t.cost,0).toFixed(2),'演示估值 · 无真实扣费']].map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#page-name').textContent=({tasks:'任务工作台',audit:'审计记录',boundary:'安全边界'})[tab];
if(tab==='audit'){$('#content').innerHTML=`<section class="panel"><div class="panel-heading"><h2>全量事件记录</h2><span>本地演示日志 · 非防篡改审计</span></div><table class="table"><thead><tr><th>时间</th><th>任务</th><th>身份</th><th>事件</th></tr></thead><tbody>${tasks.flatMap(t=>t.events.map(e=>({...e,id:t.id}))).sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<tr><td>${new Date(e.at).toLocaleTimeString()}</td><td>T${e.id}</td><td>${esc(e.actor)}</td><td>${esc(e.message)}</td></tr>`).join('')}</tbody></table></section>`;return;}
if(tab==='boundary'){$('#content').innerHTML=`<section class="panel boundary"><div class="eyebrow">SANDBOX, NOT PRODUCTION</div><h2>一个可操作的流程原型</h2><h3>已经实现</h3><p>任务登记、负责人接单、模拟执行尝试、发布与独立核验、SHA 失效、退回、取消、异常场景和日志导出。任务状态保存在本浏览器 localStorage，刷新后保留。</p><h3>明确没有实现</h3><p>真实身份认证、服务器数据库、多用户同步、GitLab 或 DSH 连接、真实 CI、操作系统隔离、费用计量和生产级访问控制。顶部身份选择只是演示工具。不要输入密钥、个人信息或敏感源码。</p><h3>生产实现需要的边界</h3><p>服务端验证平台身份与任务授权；Worker 只生成候选补丁；受控发布模块持写令牌，并在发布前检查租约；独立核验器查询 GitLab；验收绑定合同版本和提交 SHA。</p><h3>试用路线</h3><p>选择Alice创建任务 → 切换 Bob 接单 → 启动执行 → 生成产物 → 核验 → 切回Alice验收。可以在任务详情切换模拟场景，观察 CI 失败、超时或发布结果未知。</p></section>`;return;}
let t=tasks.find(t=>t.id===selected);let visible=tasks.filter(t=>filter==='all'||t.status===filter);$('#content').innerHTML=`<div class="workspace-grid"><section class="panel"><div class="panel-heading"><h2>委派任务</h2><span>${tasks.length} 个任务</span></div><select aria-label="筛选状态" class="filter" id="filter"><option value="all">全部状态</option>${Object.entries(Hub.labels).map(([k,v])=>`<option ${filter===k?'selected':''} value="${k}">${v}</option>`).join('')}</select><div class="task-list">${visible.map(t=>`<button class="task ${t.id===selected?'selected':''}" data-id="${t.id}"><div class="task-top"><span>T${t.id}　/　habitat-demo</span>${badge(t)}</div><h3>${esc(t.title)}</h3><small>Alice <span style="margin:0 8px">→</span> Bob 的 Agent　·　v${t.version}</small></button>`).join('')||'<div class="empty">此筛选下暂无任务</div>'}</div></section><section class="panel">${t?detail(t):'<div class="empty">创建你的第一个任务</div>'}</section></div>`;$('#filter').onchange=e=>{filter=e.target.value;render();};document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{Hub.act(t,b.dataset.action,$('#actor').value);save();render();toast('状态已更新并记录事件');}catch(e){toast(e.message);}});if($('#task-scenario'))$('#task-scenario').onchange=e=>{t.scenario=e.target.value;t.events.push({at:new Date().toISOString(),actor:'演示控制',message:'切换模拟场景：'+e.target.selectedOptions[0].text});save();render();};}
function detail(t){const phase={awaiting_owner:0,queued:1,working:2,verifying:3,ready:4,completed:5,failed:2,unknown:3,canceled:0}[t.status];let acts='';if(t.status==='awaiting_owner')acts=button('accept','Bob · 确认接单','primary');if(['queued','failed'].includes(t.status))acts=button('start',t.status==='failed'?'Bob · 新 attempt 重试':'Bob · 启动模拟执行','primary');if(t.status==='working')acts=button('publish','Bob · 完成执行并发布','primary');if(t.status==='verifying')acts=button('verify','Bob · 运行独立核验','primary');if(t.status==='unknown')acts=button('reconcile','Bob · 核对外部结果','primary');if(t.status==='ready')acts=button('approve','Alice · 验收通过','primary')+button('return','Alice · 退回修改')+button('stale','模拟 SHA 更新');if(!['completed','canceled'].includes(t.status))acts+=button('cancel','取消任务','secondary danger');return `<div class="detail"><div class="detail-top"><span>T${t.id}　·　合同 v${t.version}</span>${badge(t)}</div><h2>${esc(t.title)}</h2><div class="people"><span class="avatar">图</span><b>Alice</b>派活 <span>→</span><span class="avatar">R</span><b>Bob</b>负责</div><div class="steps">${['登记','授权','执行','核验','验收'].map((s,i)=>`<div class="step ${phase>=i?'done':''}"><i></i>${s}</div>`).join('')}</div><div class="description">${esc(t.description)}</div><div class="section-label">交付证据 / EVIDENCE</div><div class="facts"><div><small>目标仓库 / 分支</small><b>habitat-demo / main</b></div><div><small>执行尝试</small><b>${t.attempt?'attempt '+t.attempt:'等待接单'}</b></div><div><small>候选 MR（模拟）</small><b>${t.mr?'!'+t.mr+' · 未合并':'尚未生成'}</b></div><div><small>当前提交 SHA（模拟）</small><b>${esc(t.head||'—')}</b></div><div><small>独立核验</small><b>${t.verified&&t.verified===t.head?'✓ 当前 SHA 已验证':'未通过 / 尚未核验'}</b></div><div><small>模拟成本 / 上限</small><b>$${t.cost.toFixed(2)} / $2.00</b></div></div><div class="actions">${acts}</div><p class="help">当前体验身份：${esc($('#actor').value)}。按钮会检查角色和状态；生产环境需服务端认证。</p>${!['completed','canceled'].includes(t.status)?`<label class="help">故障注入 <select id="task-scenario" class="compact-select">${Object.entries({success:'正常交付',ci_fail:'CI 失败',timeout:'执行超时',unknown:'发布结果未知'}).map(([k,v])=>`<option value="${k}" ${t.scenario===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<div class="section-label">任务事件 / ACTIVITY</div><div class="timeline">${[...t.events].reverse().map(e=>`<div class="entry">${esc(e.message)}<small>${new Date(e.at).toLocaleTimeString()}　·　${esc(e.actor)}</small></div>`).join('')}</div></div>`;}
$('#new').onclick=()=>{if($('#actor').value!=='Alice'){toast('请切换到Alice身份发起委派');return;}$('#create').showModal();};$('#close').onclick=()=>$('#create').close();$('#form').onsubmit=e=>{e.preventDefault();const title=$('#title').value.trim(),desc=$('#description').value.trim();if(!title||!desc)return;const t=Hub.create(String(state.next++).padStart(3,'0'),title,desc,$('#scenario').value);state.tasks.unshift(t);selected=t.id;filter='all';tab='tasks';save();$('#create').close();render();toast('任务已登记，等待 Bob 接单');};$('#actor').onchange=render;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$('#reset').onclick=()=>{if(confirm('重置将清除本浏览器的演示任务，恢复两个示例。继续？')){state=seed();selected='001';save();render();toast('已恢复演示数据');}};$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({demo:true,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}));a.download='agenct-demo-audit.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};save();render();
